import type { Evidence } from "../../src/core/schemas/evidence.schema.js";

function pageSource(pageNumber: number) {
  return {
    page: {
      documentId: null,
      pageNumber,
      sheetId: null,
      sheetTitle: null,
      pageLabel: null,
      revision: null,
    },
    region: null,
    elementLabel: null,
    detailNumber: null,
    sectionNumber: null,
    scheduleName: null,
    noteReference: null,
  } as const;
}

function record(input: {
  id: string;
  subjectKind: Evidence["subjectKind"];
  subjectKey: string;
  propertyPath: string;
  candidateValue: string | number | boolean | null;
  originalText: string;
  pageNumber: number;
  type?: Evidence["type"];
}): Evidence {
  return {
    id: input.id,
    type: input.type ?? "note",
    relationship: "supports",
    description: input.propertyPath,
    source: pageSource(input.pageNumber),
    originalText: input.originalText,
    references: [],
    subjectKind: input.subjectKind,
    subjectKey: input.subjectKey,
    propertyPath: input.propertyPath,
    candidateValue: input.candidateValue,
  };
}

